    "3d-subarray-sum-markdown-code-4": "#include <cuda_runtime.h>\n\n// input, output are device pointers (i.e. pointers to memory on the GPU)\nextern \"C\" void solve(\n    const int* input,\n    int* output,\n    int N,\n    int M,\n    int K,\n    int S_DEP,\n    int E_DEP,\n    int S_ROW,\n    int E_ROW,\n    int S_COL,\n    int E_COL\n) {}",
